-- v3.0-RTI WP01: Parameter Center, Organization-as-Data (versioned, closure table), RBAC/ABAC/SoD policy data.
-- GENERATED by scripts/rti/build-migrations.cjs from src/lib/rti/*.ts. Do not edit by hand.
-- Additive only: legacy india_erp_org_units / capability grants (0034) remain the live login authority until cut-over.
-- Seed is configuration (RTI default structure), NOT identities: no users, assignments or role bindings are seeded.
CREATE TABLE india_sys_parameters(
 id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,key TEXT NOT NULL CHECK(length(key) BETWEEN 3 AND 120),
 value_json TEXT NOT NULL CHECK(json_valid(value_json)),
 verify_status TEXT NOT NULL CHECK(verify_status IN ('VERIFIED','VERIFY')),
 environment TEXT NOT NULL DEFAULT '*' CHECK(environment IN ('*','DEV','INT','UAT_SIM','STAGING','PROD')),
 effective_from TEXT NOT NULL,effective_to TEXT,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),
 status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','superseded')),
 maker TEXT NOT NULL COLLATE NOCASE,checker TEXT COLLATE NOCASE,reason TEXT NOT NULL CHECK(length(reason)>=12),
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,approved_at TEXT,
 UNIQUE(tenant_id,key,environment,effective_from,version),
 CHECK(checker IS NULL OR lower(checker)!=lower(maker)),
 CHECK(status NOT IN ('approved','rejected','superseded') OR checker IS NOT NULL),
 CHECK(effective_to IS NULL OR effective_to>effective_from)
);
CREATE INDEX india_sys_parameters_lookup ON india_sys_parameters(tenant_id,key,status,effective_from);
CREATE TRIGGER india_sys_parameters_guard BEFORE UPDATE ON india_sys_parameters
WHEN NEW.id IS NOT OLD.id OR NEW.tenant_id IS NOT OLD.tenant_id OR NEW.key IS NOT OLD.key OR NEW.value_json IS NOT OLD.value_json
 OR NEW.environment IS NOT OLD.environment OR NEW.effective_from IS NOT OLD.effective_from OR NEW.maker IS NOT OLD.maker OR NEW.reason IS NOT OLD.reason
 OR NOT ((OLD.status='pending' AND NEW.status IN ('approved','rejected') AND NEW.checker IS NOT NULL)
      OR (OLD.status='approved' AND NEW.status IN ('approved','superseded') AND OLD.effective_to IS NULL AND NEW.effective_to IS NOT NULL AND NEW.checker IS OLD.checker))
BEGIN SELECT RAISE(ABORT,'PARAMETER_IMMUTABLE'); END;
CREATE TRIGGER india_sys_parameters_no_delete BEFORE DELETE ON india_sys_parameters BEGIN SELECT RAISE(ABORT,'PARAMETER_IMMUTABLE'); END;
CREATE TABLE india_org_unit_types(
 code TEXT PRIMARY KEY CHECK(code GLOB '[A-Z]*'),allowed_parent_types_json TEXT NOT NULL CHECK(json_valid(allowed_parent_types_json)),
 can_own_budget INTEGER NOT NULL CHECK(can_own_budget IN (0,1)),can_be_profit_center INTEGER NOT NULL CHECK(can_be_profit_center IN (0,1)),
 can_hold_employees INTEGER NOT NULL CHECK(can_hold_employees IN (0,1)),version INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE india_org_units_v(
 tenant_id TEXT NOT NULL,id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>0),
 code TEXT NOT NULL,name TEXT NOT NULL CHECK(length(name) BETWEEN 2 AND 160),type TEXT NOT NULL REFERENCES india_org_unit_types(code),
 parent_id TEXT,legal_entity_id TEXT,cost_center_code TEXT,profit_center INTEGER NOT NULL DEFAULT 0 CHECK(profit_center IN (0,1)),
 business_line TEXT,location_id TEXT,currency TEXT NOT NULL DEFAULT 'IDR',
 valid_from TEXT NOT NULL,valid_to TEXT,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','closed')),
 source TEXT NOT NULL,change_request_id TEXT,
 PRIMARY KEY(tenant_id,id,version),CHECK(valid_to IS NULL OR valid_to>valid_from),CHECK(parent_id IS NULL OR parent_id!=id)
);
CREATE UNIQUE INDEX india_org_units_v_current_code ON india_org_units_v(tenant_id,code) WHERE valid_to IS NULL AND status='active';
CREATE UNIQUE INDEX india_org_units_v_current_id ON india_org_units_v(tenant_id,id) WHERE valid_to IS NULL;
CREATE TRIGGER india_org_units_v_parent BEFORE INSERT ON india_org_units_v
WHEN NEW.parent_id IS NOT NULL AND NOT EXISTS(
 SELECT 1 FROM india_org_units_v p JOIN india_org_unit_types t ON t.code=NEW.type
 WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.parent_id AND p.status='active' AND p.valid_from<=NEW.valid_from AND (p.valid_to IS NULL OR p.valid_to>NEW.valid_from)
 AND EXISTS(SELECT 1 FROM json_each(t.allowed_parent_types_json) a WHERE a.value=p.type))
BEGIN SELECT RAISE(ABORT,'ORG_PARENT_TYPE_INVALID'); END;
CREATE TRIGGER india_org_units_v_profit BEFORE INSERT ON india_org_units_v
WHEN NEW.profit_center=1 AND NOT EXISTS(SELECT 1 FROM india_org_unit_types t WHERE t.code=NEW.type AND t.can_be_profit_center=1)
BEGIN SELECT RAISE(ABORT,'ORG_PROFIT_CENTER_NOT_ALLOWED'); END;
CREATE TRIGGER india_org_units_v_history BEFORE UPDATE ON india_org_units_v
WHEN OLD.valid_to IS NOT NULL OR NEW.valid_to IS NULL OR NEW.tenant_id IS NOT OLD.tenant_id OR NEW.id IS NOT OLD.id OR NEW.version IS NOT OLD.version
 OR NEW.code IS NOT OLD.code OR NEW.name IS NOT OLD.name OR NEW.type IS NOT OLD.type OR NEW.parent_id IS NOT OLD.parent_id
 OR NEW.legal_entity_id IS NOT OLD.legal_entity_id OR NEW.profit_center IS NOT OLD.profit_center OR NEW.valid_from IS NOT OLD.valid_from
BEGIN SELECT RAISE(ABORT,'ORG_HISTORY_IMMUTABLE'); END;
CREATE TRIGGER india_org_units_v_no_delete BEFORE DELETE ON india_org_units_v BEGIN SELECT RAISE(ABORT,'ORG_HISTORY_IMMUTABLE'); END;
CREATE TABLE india_org_closure(
 tenant_id TEXT NOT NULL,ancestor TEXT NOT NULL,descendant TEXT NOT NULL,depth INTEGER NOT NULL CHECK(depth>=0),
 built_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,ancestor,descendant)
);
CREATE INDEX india_org_closure_desc ON india_org_closure(tenant_id,descendant);
CREATE TABLE india_org_positions(
 tenant_id TEXT NOT NULL,id TEXT NOT NULL,org_unit_id TEXT NOT NULL,title TEXT NOT NULL CHECK(length(title) BETWEEN 3 AND 120),
 grade TEXT,reports_to_position_id TEXT,is_head INTEGER NOT NULL DEFAULT 0 CHECK(is_head IN (0,1)),headcount_budget INTEGER NOT NULL DEFAULT 1 CHECK(headcount_budget>=0),
 valid_from TEXT NOT NULL,valid_to TEXT,created_by TEXT NOT NULL COLLATE NOCASE,
 PRIMARY KEY(tenant_id,id),CHECK(reports_to_position_id IS NULL OR reports_to_position_id!=id)
);
CREATE UNIQUE INDEX india_org_one_head ON india_org_positions(tenant_id,org_unit_id) WHERE is_head=1 AND valid_to IS NULL;
CREATE TABLE india_org_assignments(
 tenant_id TEXT NOT NULL,id TEXT NOT NULL,position_id TEXT NOT NULL,email TEXT NOT NULL COLLATE NOCASE,
 kind TEXT NOT NULL CHECK(kind IN ('DEFINITIVE','ACTING','PLT','CONCURRENT')),valid_from TEXT NOT NULL,valid_to TEXT,
 created_by TEXT NOT NULL COLLATE NOCASE,approved_by TEXT COLLATE NOCASE,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),
 PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,position_id) REFERENCES india_org_positions(tenant_id,id),
 CHECK(approved_by IS NULL OR (lower(approved_by)!=lower(created_by) AND lower(approved_by)!=lower(email))),
 CHECK(valid_to IS NULL OR valid_to>valid_from)
);
CREATE TABLE india_org_relations(
 tenant_id TEXT NOT NULL,id TEXT NOT NULL,from_position_id TEXT NOT NULL,to_position_id TEXT NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('FUNCTIONAL','PROJECT','SOLID_LINE','DOTTED_LINE')),valid_from TEXT NOT NULL,valid_to TEXT,
 PRIMARY KEY(tenant_id,id),CHECK(from_position_id!=to_position_id)
);
CREATE TABLE india_org_change_requests(
 tenant_id TEXT NOT NULL,id TEXT NOT NULL,op TEXT NOT NULL CHECK(op IN ('create','rename','move','merge','split','close')),
 payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),effective_date TEXT NOT NULL,impact_json TEXT CHECK(impact_json IS NULL OR json_valid(impact_json)),
 required_approvers_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(required_approvers_json)),
 approvals_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(approvals_json)),
 status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','applied')),
 maker TEXT NOT NULL COLLATE NOCASE,reason TEXT NOT NULL CHECK(length(reason)>=12),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,applied_at TEXT,
 PRIMARY KEY(tenant_id,id)
);
CREATE TRIGGER india_org_change_flow BEFORE UPDATE ON india_org_change_requests
WHEN NEW.tenant_id IS NOT OLD.tenant_id OR NEW.id IS NOT OLD.id OR NEW.op IS NOT OLD.op OR NEW.payload_json IS NOT OLD.payload_json
 OR NEW.effective_date IS NOT OLD.effective_date OR NEW.maker IS NOT OLD.maker
 OR EXISTS(SELECT 1 FROM json_each(NEW.approvals_json) a WHERE lower(json_extract(a.value,'$.by'))=lower(OLD.maker))
 OR NOT ((OLD.status='pending' AND NEW.status IN ('pending','approved','rejected')) OR (OLD.status='approved' AND NEW.status='applied'))
BEGIN SELECT RAISE(ABORT,'ORG_CHANGE_INVALID'); END;
CREATE TRIGGER india_org_change_no_delete BEFORE DELETE ON india_org_change_requests BEGIN SELECT RAISE(ABORT,'ORG_CHANGE_INVALID'); END;
CREATE TABLE india_iam_permissions(
 code TEXT PRIMARY KEY CHECK(code GLOB '[a-z*]*.[a-z_*]*.[a-z*]*'),module TEXT NOT NULL,resource TEXT NOT NULL,action TEXT NOT NULL,source TEXT NOT NULL
);
CREATE TABLE india_iam_role_templates(
 code TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,group_name TEXT NOT NULL,scope TEXT NOT NULL CHECK(scope IN ('own','project','unit','unit_tree','entity','all','own_tenant')),
 mfa INTEGER NOT NULL CHECK(mfa IN (0,1)),pam INTEGER NOT NULL DEFAULT 0 CHECK(pam IN (0,1)),permissions_json TEXT NOT NULL CHECK(json_valid(permissions_json)),
 status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','retired')),maker TEXT NOT NULL COLLATE NOCASE,checker TEXT COLLATE NOCASE,
 PRIMARY KEY(code,version),CHECK(checker IS NULL OR lower(checker)!=lower(maker))
);
CREATE TABLE india_iam_role_bindings(
 tenant_id TEXT NOT NULL,id TEXT NOT NULL,template_code TEXT NOT NULL,template_version INTEGER NOT NULL,
 subject_kind TEXT NOT NULL CHECK(subject_kind IN ('position','user')),subject_ref TEXT NOT NULL COLLATE NOCASE,
 org_unit_id TEXT NOT NULL,legal_entity_id TEXT NOT NULL,valid_from TEXT NOT NULL,valid_to TEXT,
 status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','revoked')),
 granted_by TEXT NOT NULL COLLATE NOCASE,approved_by TEXT COLLATE NOCASE,sod_mitigation_ref TEXT,reason TEXT NOT NULL CHECK(length(reason)>=12),
 PRIMARY KEY(tenant_id,id),FOREIGN KEY(template_code,template_version) REFERENCES india_iam_role_templates(code,version),
 CHECK(approved_by IS NULL OR lower(approved_by)!=lower(granted_by)),
 CHECK(subject_kind!='user' OR lower(subject_ref)!=lower(granted_by)),
 CHECK(approved_by IS NULL OR subject_kind!='user' OR lower(approved_by)!=lower(subject_ref))
);
CREATE INDEX india_iam_role_bindings_subject ON india_iam_role_bindings(tenant_id,subject_kind,subject_ref,status);
CREATE TRIGGER india_iam_role_bindings_no_delete BEFORE DELETE ON india_iam_role_bindings BEGIN SELECT RAISE(ABORT,'BINDING_IMMUTABLE'); END;
CREATE TABLE india_iam_sod_rules(
 id TEXT PRIMARY KEY,conflict_a TEXT NOT NULL,conflict_b TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN ('Critical','High','Medium')),
 same_object INTEGER NOT NULL CHECK(same_object IN (0,1)),description TEXT NOT NULL,mitigation TEXT
);
CREATE TABLE india_iam_abac_policies(
