INSERT INTO india_iam_sod_rules(id,conflict_a,conflict_b,severity,same_object,description) VALUES
 ('SOD-01','prc.vendor.create','trs.payment.approve','Critical',0,'Create vendor master vs approve/release payment'),
 ('SOD-02','prc.po.create','prc.goods_receipt.create','High',1,'Create PO vs record goods receipt for the same PO'),
 ('SOD-03','fin.journal.post','fin.close.approve','Critical',0,'Post journal vs approve period close'),
 ('SOD-04','ar.invoice.create','ar.cash_receipt.create','High',0,'Create customer invoice vs record cash receipt'),
 ('SOD-05','hr.payroll_master.edit','hr.payroll.approve','Critical',0,'Edit payroll master vs approve payroll run'),
 ('SOD-06','iam.binding.create','*held_role*','Critical',1,'Grant a role vs hold that role'),
 ('SOD-07','cpq.pricing.edit','cpq.quotation.approve','High',1,'Set pricing/discount vs approve own quotation'),
 ('SOD-08','cyb.finding.edit','cyb.finding.approve','Medium',1,'Pentester edits finding vs QA approves the same finding'),
 ('SOD-09','swe.release.deploy','swe.release.approve','Critical',1,'Developer deploys to PROD vs approves release');
INSERT INTO india_iam_abac_policies(id,policy_json) VALUES
 ('ABAC-POSTED-IMMUTABLE','{"id":"ABAC-POSTED-IMMUTABLE","effect":"deny","when":[{"attr":"resource.status","op":"in","value":["POSTED","posted","HARD_CLOSED"]},{"attr":"action","op":"in","value":["edit","delete"]}],"message":"Dokumen POSTED tidak dapat diubah; gunakan reversal"}'),
 ('ABAC-RESTRICTED-MEMBERS','{"id":"ABAC-RESTRICTED-MEMBERS","effect":"deny","when":[{"attr":"resource.classification","op":"eq","value":"RESTRICTED"}],"unless":[{"attr":"resource.project_members","op":"subject_in"}],"message":"Data RESTRICTED hanya untuk member engagement"}'),
 ('ABAC-PROD-NO-IMPERSONATE','{"id":"ABAC-PROD-NO-IMPERSONATE","effect":"deny","when":[{"attr":"subject.environment","op":"eq","value":"PROD"},{"attr":"action","op":"eq","value":"impersonate"}],"message":"Impersonation dilarang di PROD"}');
